-- PSY240 class trial, review before launch (Oct 13, the day before the baseline opens).
--
-- 1. "Prefer not to answer" on every questionnaire item. The trial's consent says
--    "You can choose 'Prefer not to answer' on any question", but the two arm
--    measures were legacy item definitions with no opt-out (psy240-mpod-t, 15
--    items; smm-8, 8 items), and "Your four weeks" (class-trial-experience) had
--    allow_pna false. MPoD-t and SMM become composable definitions, converted
--    with the production converter (src/lib/legacyToStacked.js) exactly as the
--    study's stacked layout already showed them: same item ids, published order,
--    same pages and labels. Then allow_pna on every item. Scoring kept as
--    documentation.
--
-- 2. Three instructed-response attention checks (Norm: "a few catch trials to
--    gauge attention in baseline and post"). Both surveys use the same
--    questionnaires, so each check appears at both timepoints. Each check sits
--    mid-page with a different target answer, so straight-lining at either end
--    fails at least one. As in Sense Foraging Study 2: required, no "Prefer not
--    to answer", ids ending in a word so the export names them by id, never as an
--    item number (website.md §23, export naming trap):
--      mpodt_attn_check     MPoD-t page 1, after mpod_5        select 2
--      spane_attn_check     SPANE page 2, after SPANE_9        select "Rarely" (2)
--      flourish_attn_check  Flourishing page 2, after Meaning_6 select "Slightly Disagree" (3)
--    Each definition records its key in attention_checks [{id, correct}].
--    The Sense Foraging short form (psy240-sf-short-20) is left identical to
--    the research instrument (sf-short-20), which carries no check.
--
-- All five questionnaires are used only by the class trial's templates and have no
-- responses (trial inactive, no enrollments). Every definition passes
-- validateComposableDefinition. Generated from the live definitions; the full
-- definitions are written out below.

update questionnaires set definition = $def${"slug":"psy240-mpod-t","name":"Thoughts and feelings","questionnaire_type":"composable","instructions":"How much do you agree or disagree with each statement? Answer from 1 (strongly disagree) to 7 (strongly agree). There are no right or wrong answers.","pages":[{"id":"v2_p1","components":[{"id":"v2_instructions_p1","type":"information","title":"","body":"How much do you agree or disagree with each statement? Answer from 1 (strongly disagree) to 7 (strongly agree). There are no right or wrong answers.","image_url":"","image_alt":""},{"id":"mpod_1","type":"likert","question":"I am able to watch myself thinking.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_2","type":"likert","question":"I can watch my thoughts and emotions come and go like clouds.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_3","type":"likert","question":"I am able to step back and watch my mind work.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_4","type":"likert","question":"I am able to watch my thoughts and feelings like someone watching a movie.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_5","type":"likert","question":"I can watch my thoughts and emotions drift by like leaves on a stream.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpodt_attn_check","type":"likert","question":"To show that you are reading each statement, please select 2 for this one.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true},{"id":"mpod_6","type":"likert","question":"My thoughts and emotions are part of me, but they are not me.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_7","type":"likert","question":"I am more than my thoughts and feelings.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_8","type":"likert","question":"I am separate from my changing thoughts and feelings.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true}]},{"id":"v2_p2","components":[{"id":"v2_instructions_p2","type":"information","title":"","body":"How much do you agree or disagree with each statement? Answer from 1 (strongly disagree) to 7 (strongly agree). There are no right or wrong answers.","image_url":"","image_alt":""},{"id":"mpod_9","type":"likert","question":"My sense of self is larger than my thoughts and feelings.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_10","type":"likert","question":"My sense of self is separate from my changing thoughts and feelings.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_11","type":"likert","question":"I can be aware of unpleasant thoughts or feelings without immediately reacting to them.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_12","type":"likert","question":"When I have distressing thoughts or feelings I am able to notice them without reacting.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_13","type":"likert","question":"When I have distressing thoughts or emotions, I just notice them and let them go.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_14","type":"likert","question":"I can observe unpleasant thoughts and feelings without trying to change them.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"mpod_15","type":"likert","question":"I can step back and be aware of distressing thoughts and emotions without being taken over by them.","scale":[{"value":1,"label":"Strongly Disagree"},{"value":2,"label":""},{"value":3,"label":""},{"value":4,"label":""},{"value":5,"label":""},{"value":6,"label":""},{"value":7,"label":"Strongly Agree"}],"required":true,"allow_pna":true}]}],"scoring":{"method":"mean","subscales":[{"name":"Metaawareness","item_ids":["mpod_1","mpod_2","mpod_3","mpod_4","mpod_5"],"reverse_items":[]},{"name":"(Dis)Identification","item_ids":["mpod_6","mpod_7","mpod_8","mpod_9","mpod_10"],"reverse_items":[]},{"name":"(Non)Reactivity","item_ids":["mpod_11","mpod_12","mpod_13","mpod_14","mpod_15"],"reverse_items":[]}]},"attention_checks":[{"id":"mpodt_attn_check","correct":2}]}$def$::jsonb
 where slug = 'psy240-mpod-t';

update questionnaires set definition = $def${"slug":"smm-8","name":"Views about stress","questionnaire_type":"composable","instructions":"Rate the extent to which you agree or disagree with the following questions.","pages":[{"id":"v2_p1","components":[{"id":"v2_instructions_p1","type":"information","title":"","body":"Rate the extent to which you agree or disagree with the following questions.","image_url":"","image_alt":""},{"id":"smm_1","type":"likert","question":"The effects of stress are negative and should be avoided.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"smm_2","type":"likert","question":"Experiencing stress facilitates my learning and growth.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"smm_3","type":"likert","question":"Experiencing stress depletes my health and vitality.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"smm_4","type":"likert","question":"Experiencing stress enhances my performance and productivity.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"smm_5","type":"likert","question":"Experiencing stress inhibits my learning and growth.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"smm_6","type":"likert","question":"Experiencing stress improves my health and vitality.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"smm_7","type":"likert","question":"Experiencing stress debilitates my performance and productivity.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true},{"id":"smm_8","type":"likert","question":"The effects of stress are positive and should be utilized.","scale":[{"value":0,"label":"Strongly Disagree"},{"value":1,"label":"Disagree"},{"value":2,"label":"Neither Agree nor Disagree"},{"value":3,"label":"Agree"},{"value":4,"label":"Strongly Agree"}],"required":true,"allow_pna":true}]}],"scoring":{"method":"mean","subscales":[{"name":"Stress mindset","item_ids":["smm_1","smm_2","smm_3","smm_4","smm_5","smm_6","smm_7","smm_8"],"reverse_items":["smm_1","smm_3","smm_5","smm_7"]}]}}$def$::jsonb
 where slug = 'smm-8';

