update questionnaires set definition = $def${"name":"How things are going","slug":"psy240-utmap-flourishing","pages":[{"id":"flourish_p1","components":[{"id":"flourish_info","body":"Below are 8 statements with which you may agree or disagree. Using the 1 to 7 scale, indicate your agreement with each item.","type":"information","title":"Agree or disagree","image_alt":"","image_url":""},{"id":"Meaning_1","type":"likert","scale":[{"label":"Strongly Disagree","value":1},{"label":"Disagree","value":2},{"label":"Slightly Disagree","value":3},{"label":"Mixed or neither agree nor disagree","value":4},{"label":"Slightly Agree","value":5},{"label":"Agree","value":6},{"label":"Strongly Agree","value":7}],"question":"I lead a purposeful and meaningful life.","required":true,"allow_pna":true},{"id":"Meaning_2","type":"likert","scale":[{"label":"Strongly Disagree","value":1},{"label":"Disagree","value":2},{"label":"Slightly Disagree","value":3},{"label":"Mixed or neither agree nor disagree","value":4},{"label":"Slightly Agree","value":5},{"label":"Agree","value":6},{"label":"Strongly Agree","value":7}],"question":"My social relationships are supportive and rewarding.","required":true,"allow_pna":true},{"id":"Meaning_3","type":"likert","scale":[{"label":"Strongly Disagree","value":1},{"label":"Disagree","value":2},{"label":"Slightly Disagree","value":3},{"label":"Mixed or neither agree nor disagree","value":4},{"label":"Slightly Agree","value":5},{"label":"Agree","value":6},{"label":"Strongly Agree","value":7}],"question":"I am engaged and interested in my daily activities.","required":true,"allow_pna":true},{"id":"Meaning_4","type":"likert","scale":[{"label":"Strongly Disagree","value":1},{"label":"Disagree","value":2},{"label":"Slightly Disagree","value":3},{"label":"Mixed or neither agree nor disagree","value":4},{"label":"Slightly Agree","value":5},{"label":"Agree","value":6},{"label":"Strongly Agree","value":7}],"question":"I actively contribute to the happiness and well-bein