e","value":5},{"label":"Agree","value":6},{"label":"Strongly Agree","value":7}],"question":"People respect me.","required":true,"allow_pna":true}]}],"questionnaire_type":"composable","attention_checks":[{"id":"flourish_attn_check","correct":3}]}$def$::jsonb
 where slug = 'psy240-utmap-flourishing';

update questionnaires set definition = $def${"name":"Your four weeks","slug":"class-trial-experience","pages":[{"id":"experience","components":[{"id":"Enjoyed","type":"likert","scale":[{"label":"Not at all","value":1},{"label":"A little","value":2},{"label":"Somewhat","value":3},{"label":"Quite a bit","value":4},{"label":"Very much","value":5}],"question":"How much did you enjoy the daily practice?","required":true,"allow_pna":true},{"id":"Helped","type":"likert","scale":[{"label":"Not at all","value":1},{"label":"A little","value":2},{"label":"Somewhat","value":3},{"label":"Quite a bit","value":4},{"label":"Very much","value":5}],"question":"How much did the daily practice help you?","required":true,"allow_pna":true},{"id":"Continue","type":"likert","scale":[{"label":"Definitely not","value":1},{"label":"Probably not","value":2},{"label":"Not sure","value":3},{"label":"Probably yes","value":4},{"label":"Definitely yes","value":5}],"question":"Would you keep doing a practice like this?","required":true,"allow_pna":true},{"id":"StoodOut","rows":4,"type":"open_text","question":"What stood out for you about the four weeks?","required":false,"multiline":true,"placeholder":"A sentence is enough."}]}],"questionnaire_type":"composable"}$def$::jsonb
 where slug = 'class-trial-experience';
